using System;
using System.IO;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using CashflowChains.City;
using CashflowChains.Economy;
using CashflowChains.Empire;

public sealed class ExistingCityTests {
 BalanceConfig c;
 [SetUp]public void Setup(){c=JsonUtility.FromJson<BalanceConfig>(File.ReadAllText(Path.Combine(Application.dataPath,"_Game/Data/CC2/balance-v1.json")));c.Validate();}
 EmpireEngine Investor(){var e=new EmpireEngine(c,new EmpireAccount{Economy=new EconomyState{AccountId="existing-city"}},_=>true);e.OpenCity(100);e.EnterExistingCity(101);return e;}
 [Test]public void EstablishedCityHasRealPublicHouseholdsAndNoPrivateFreeIncome(){var e=Investor();var r=e.ForecastCity();Assert.AreEqual(0,e.Snapshot.City.Properties.Count);Assert.AreEqual(48,r.PublicResidents);Assert.AreEqual(48,r.Population);Assert.AreEqual(18,r.Households);Assert.AreEqual(0,r.PrivateResidents);Assert.AreEqual(24,r.PublicJobs);Assert.AreEqual(30,r.Workers);Assert.AreEqual(0,r.Jobs);Assert.AreEqual(6,e.Snapshot.City.Workers(c.City));Assert.AreEqual(0,r.Revenue);Assert.AreEqual(0,r.Bills);Assert.AreEqual(0,r.Net);Assert.IsEmpty(r.Businesses);Assert.AreEqual(200,e.Snapshot.Economy.Amount("CASH"));}
 [Test]public void RegionEntryIsIdempotentAndCannotManufactureRentOrMaterials(){var e=Investor();var before=e.Snapshot;e.EnterExistingCity(102);Assert.AreEqual(before.Economy.Revision,e.Snapshot.Economy.Revision);Assert.AreEqual(before.Economy.Amount("CASH"),e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(0,e.AdvanceCityTo(200));Assert.AreEqual(0,e.Snapshot.City.LastDayRevenue);}
 [Test]public void FirstInvestmentCapitalCannotBeLostToLandUtilitiesOrMaterialShopping(){var e=Investor();Assert.Throws<InvalidOperationException>(()=>e.ExpandCity("early-land",true,102));Assert.Throws<InvalidOperationException>(()=>e.ImproveCityGrid("early-utility",102));e.BuyCityMaterials("allowed-supplies","WOOD",20,102);Assert.AreEqual(140,e.Snapshot.Economy.Amount("CASH"));Assert.Throws<InvalidOperationException>(()=>e.BuyCityMaterials("capital-exhaustion","STEEL",20,103));e.BuildCity("funded-rental","home",1,1,104);e.AdvanceCityTo(112);Assert.Greater(e.Snapshot.City.EarnedCashflow,0);}
 [Test]public void RegionalStateAndEarnedCashflowRemainBoundToActualReceipts(){var e=Investor();var state=e.Snapshot;state.City.Region=0;Assert.Throws<ArgumentException>(()=>state.Validate(c));state=e.Snapshot;state.City.EarnedCashflow=100000;Assert.Throws<ArgumentException>(()=>state.Validate(c));}
 [Test]public void FirstRentalOperatesWithoutOwningACafeAndUnlocksARealCareerStep(){var e=Investor();Assert.Throws<InvalidOperationException>(()=>e.BuildCity("premature-cafe","cafe",2,1,102));e.BuildCity("rental","home",1,1,103);e.AdvanceCityTo(106);Assert.AreEqual(1,e.Snapshot.City.CareerStage);Assert.AreEqual(52,e.ForecastCity().Population);Assert.AreEqual(120,e.Snapshot.Economy.Amount("CASH"));e.AdvanceCityTo(111);Assert.AreEqual(2,e.Snapshot.City.Day);Assert.AreEqual(17,e.Snapshot.City.EarnedCashflow);Assert.AreEqual(2,e.Snapshot.City.CareerStage);Assert.AreEqual(137,e.Snapshot.Economy.Amount("CASH"));e.BuildCity("later-cafe","cafe",2,1,112);Assert.AreEqual(37,e.Snapshot.Economy.Amount("CASH"));}
 [Test]public void MarketStallIsARealAlternativeFirstInvestment(){var e=Investor();Assert.IsTrue(e.QuoteCityInvestment("grocer",1,1).Unlocked);Assert.Greater(e.QuoteCityInvestment("grocer",1,1).AfterNet,0);e.BuildCity("market","grocer",1,1,102);e.AdvanceCityTo(110);var r=e.CurrentCityDay();Assert.Greater(r.Businesses.Single().Customers,0);Assert.Greater(r.Resources.Single(x=>x.ItemId=="PRODUCE").Consumed,0);Assert.Greater(r.ImportBills,0);Assert.AreEqual(0,r.PrivateResidents);Assert.AreEqual(48,r.Population);Assert.Greater(e.Snapshot.City.LifetimeRevenue,0);Assert.IsTrue(r.Flows.Any(f=>f.Kind=="GROCERIES"));}
 [Test]public void PublicEmploymentIsReservedAndEveryPrivateSaleConsumesRealStock(){var e=Investor();e.BuildCity("rental","home",1,1,102);e.AdvanceCityTo(110);e.BuildCity("cafe","cafe",2,1,111);e.AdvanceCityTo(114);var r=e.ForecastCity();Assert.LessOrEqual(r.Jobs,r.Workers-r.PublicJobs);Assert.Greater(r.CoffeeServed,0);Assert.LessOrEqual(r.CoffeeServed,r.CoffeeDemand);Assert.AreEqual(r.CoffeeServed,r.Resources.Single(x=>x.ItemId=="BEANS").Consumed);Assert.AreEqual(r.CoffeeServed,r.Resources.Single(x=>x.ItemId=="CUPS").Consumed);Assert.IsTrue(r.Flows.Any(f=>f.Source>=1000&&f.Kind=="CUSTOMER"));Assert.IsTrue(r.Flows.Any(f=>f.Source==1107&&f.Kind=="BEANS"));Assert.IsTrue(r.Businesses.All(b=>b.PropertyId<1000));}
 [Test]public void PublicBuildingsCannotBeMovedPausedUpgradedOrMadeIntoPrivateRent(){var e=Investor();Assert.Throws<ArgumentException>(()=>e.MoveCityProperty("steal",1000,1,1,102));Assert.Throws<ArgumentException>(()=>e.SetCityOpen("pause-city",1102,false,102));Assert.Throws<ArgumentException>(()=>e.UpgradeCity("upgrade-city",1000,102));Assert.Throws<ArgumentException>(()=>e.SetCityPrice("price-city",1000,12500,102));Assert.AreEqual(200,e.Snapshot.Economy.Amount("CASH"));}
 [Test]public void EnteringRegionDoesNotRewriteAnAlreadyCommittedLegacyDay(){var e=new EmpireEngine(c,new EmpireAccount{Economy=new EconomyState{AccountId="entry-migration"}},_=>true);e.OpenCity(100);e.BuildCity("home","home",1,1,101);e.FinishCityBuild("home",104);e.BuildCity("cafe","cafe",2,1,105);e.FinishCityBuild("cafe",108);e.StartCityDay(109);var original=e.CurrentCityDay();e.EnterExistingCity(110);Assert.AreEqual(original.Net,e.CurrentCityDay().Net);Assert.AreEqual(0,e.Snapshot.City.Trading.Region);var loaded=JsonUtility.FromJson<EmpireAccount>(JsonUtility.ToJson(e.Snapshot));loaded.Validate(c);var copy=new EmpireEngine(c,loaded,_=>true);copy.AdvanceCityTo(114);Assert.AreEqual(1,copy.Snapshot.City.Region);Assert.AreEqual(48,copy.ForecastCity().PublicResidents);Assert.AreEqual(1,copy.Snapshot.Economy.Receipts.Count(r=>r.CommandId=="city-day-settle:1"));}
 [Test]public void AnOwnedHotelCanServeRegionalVisitorsWithoutOwningPublicTransport(){var plan=new CityOperatingPlan{Region=1,HousingRules=2,Day=6,StartAt=100,FinishAt=145,CashAvailable=1000,Properties=new[]{new CityProperty{Id=1,Kind="hotel",Level=1,X=1,Y=1}},Inventory=new ItemAmount[0]};var r=CityDayModel.Forecast(c.City,plan);Assert.AreEqual(8,r.RegionalVisitors);Assert.Greater(r.Visitors,0);Assert.LessOrEqual(r.Visitors,8);Assert.Greater(r.Businesses.Single().Revenue,0);Assert.IsTrue(r.Flows.Any(f=>f.Source==1106&&f.Kind=="CUSTOMER"));Assert.IsFalse(r.Businesses.Any(b=>b.Kind=="port"));}
 [Test]public void PublicBuildingsStayOutsideEveryPrivateExpansionAndHaveUniqueAddresses(){Assert.AreEqual(CityRegion.Buildings.Length,CityRegion.Buildings.Select(b=>b.Id).Distinct().Count());Assert.AreEqual(CityRegion.Buildings.Length,CityRegion.Buildings.Select(b=>b.X+":"+b.Y).Distinct().Count());foreach(var b in CityRegion.Buildings){Assert.IsTrue(b.X<0||b.Y<0);for(int size=4;size<=12;size+=2)Assert.IsFalse(b.X>=0&&b.Y>=0&&b.X<size&&b.Y<size);}}
 [Test]public void PublicAndPrivateEconomicRoutesUseActualAccessStreets(){var p=CityRegion.Footprints.Concat(new[]{new CityProperty{Id=1,Kind="home",X=1,Y=1},new CityProperty{Id=2,Kind="cafe",X=3,Y=3}}).ToArray();var streets=new CityStreets(p);foreach(var a in p)foreach(var b in p){int x=a.X+1,y=a.Y+1;while(x!=b.X+1){int next=x+Math.Sign(b.X+1-x);Assert.IsTrue(streets.HasRoad(x,y,next,y));x=next;}while(y!=b.Y+1){int next=y+Math.Sign(b.Y+1-y);Assert.IsTrue(streets.HasRoad(x,y,x,next));y=next;}}}
 [Test]public void MarketCalendarChangesOnlyDisclosedFiniteConditions(){Assert.AreEqual(4,CityRegion.Market(1).ExtraImportCapacity);Assert.AreEqual(1,CityRegion.Market(2).ExtraShoppingNeed);Assert.AreEqual(0,CityRegion.Market(3).ExtraShoppingNeed);var e=Investor();var r=e.ForecastCity();Assert.AreEqual(16,r.RegionalImportCapacity);Assert.AreEqual("WHOLESALE DELIVERY",r.Market);Assert.AreEqual(48,r.PublicResidents);Assert.AreEqual(0,r.Revenue);}
}
